def create_share_rotation(
    self, wallet_id: str, rotation_id: object
) -> tuple[int, dict]:
    """准备一次份额轮换：生成两份新份额，私钥只落暂存文件。

    返回 (HTTP 状态码, 响应体)。同 rotation_id 重放返回 200 且不重新
    生成；每钱包同时只允许一个 prepared 轮换，冲突返回 409。

    恢复检查、钱包存在性、rotation_id 校验、查重与 prepared 冲突判定
    全部在锁内：绝不基于锁外快照决定 404/400/409 或幂等重放。
    """
    record: dict | None = None
    try:
        with self._wallet_lock(wallet_id):
            self._heal_wallet(wallet_id)
            # 404 优先于 400：存在性先于 rotation_id 校验
            self._get_wallet_or_404(wallet_id)
            self._assert_wallet_active_locked(wallet_id)
            self._validate_rotation_id(rotation_id)
            existing = self._store.get_rotation(wallet_id, rotation_id)
            if existing is not None:
                # 幂等重放：原样返回，不重新生成、不记事件
                return 200, self._rotation_view(existing)
            for other in self._store.list_rotations(wallet_id):
                if other.get("state") in ("prepared", "activating"):
                    raise ServiceError(
                        409,
                        f"wallet {wallet_id!r} already has a prepared "
                        "share rotation",
                    )
            share_ids = [
                f"{rotation_id}-share-1",
                f"{rotation_id}-share-2",
            ]
            share_keys = [
                crypto.generate_share_key(sid) for sid in share_ids
            ]
            public_key = crypto.combine_public_keys(
                [k.public_bytes for k in share_keys]
            ).hex()
            record = {
                "rotation_id": rotation_id,
                "state": "prepared",
                "share_ids": share_ids,
                "public_key": public_key,
                "created_at": _utc_now_iso(),
            }
            try:
                # 新份额私钥只写入暂存文件（一份一个文件），激活前绝不
                # 触碰在用份额与钱包元数据
                for key in share_keys:
                    self._store.save_staging_share(
                        wallet_id,
                        rotation_id,
                        {
                            "share_id": key.share_id,
                            "public_key": key.public_bytes.hex(),
                            # 仅该份额自己的私钥；系统中不存在完整私钥
                            "private_key": key.private_bytes.hex(),
                        },
                    )
                self._store.create_rotation(wallet_id, rotation_id, record)
                self._emit(
                    wallet_id,
                    self._audit_event(
                        audit.TYPE_SHARE_ROTATION_PREPARED,
                        details={
                            "rotation_id": rotation_id,
                            "share_ids": share_ids,
                            "public_key": public_key,
                        },
                    ),
                )
            except BaseException:
                # 状态/事件原子：事件未落盘则回滚轮换记录与暂存文件
                self._store.delete_rotation(wallet_id, rotation_id)
                self._store.delete_staging(wallet_id, rotation_id)
                raise
    except CorruptDataError:
        raise
    except ValueError:
        # wallet_id 含非法字符（构造锁路径时抛出）
        raise ServiceError(400, "invalid wallet_id")
    return 201, self._rotation_view(record)

def get_share_rotation(self, wallet_id: str, rotation_id: str) -> dict:
    try:
        with self._wallet_lock(wallet_id):
            self._heal_wallet(wallet_id)
            # 钱包存在性先于轮换读取：绝不先用锁外快照决定 404
            self._get_wallet_or_404(wallet_id)
            # 锁内读取：并发激活期间不会读到瞬态 activating
            try:
                record = self._store.get_rotation(wallet_id, rotation_id)
            except CorruptDataError:
                raise
            except ValueError:
                raise ServiceError(400, "invalid rotation_id")
            if record is None:
                raise ServiceError(
                    404, f"share rotation {rotation_id!r} not found"
                )
            return self._rotation_view(record)
    except CorruptDataError:
        raise
    except ValueError:
        raise ServiceError(400, "invalid wallet_id")

def activate_share_rotation(
    self, wallet_id: str, rotation_id: str

        def do_DELETE(self) -> None:  # noqa: N802
            self._reject_unsupported_method()

        def do_PATCH(self) -> None:  # noqa: N802
            self._reject_unsupported_method()

        def do_OPTIONS(self) -> None:  # noqa: N802
            self._reject_unsupported_method()

        def do_HEAD(self) -> None:  # noqa: N802
            # HEAD 语义不返回响应体：audit-integrity / audit-evidence、
            # asset-consistency 与会话/轮换 cancel 路径上仅给 405 状态头。
            self._compact_response = False
            path = urlparse(self.path).path
            matched = self._split_wallet_path(path)
            if matched is not None and (
                matched[1]
                in (
                    ["audit-integrity"],
                    ["audit-evidence"],
                    ["asset-consistency"],
                )
                or self._is_cancel_path(matched[1])
            ):
                self.send_response(405)
                self.send_header(
                    "Allow",
                    "GET"
                    if matched[1]
                    in (
                        ["audit-integrity"],
                        ["audit-evidence"],
                    )
                    else "POST",
                )
                self.send_header("Content-Length", "0")
                self.end_headers()
            else:
                self._send_error(404, "not found")

        def _reject_unsupported_method(self) -> None:
            """audit-integrity / audit-evidence 资源、asset-consistency
            与签名会话/份额轮换 cancel 路径上的 DELETE/PATCH/OPTIONS/HEAD
            一律抛 ServiceError(405)；其余路径保持 404。"""
            self._compact_response = False
            try:
                path = urlparse(self.path).path
                matched = self._split_wallet_path(path)
                if matched is not None and (
                    matched[1]
                    in (
                        ["audit-integrity"],
                        ["audit-evidence"],
                        ["asset-consistency"],
                    )
                    or self._is_cancel_path(matched[1])
                ):
                    raise ServiceError(405, "method not allowed")
                self._send_error(404, "not found")
            except Exception as exc:
                self._send_failure(exc)

        # ---- 路径匹配 ---------------------------------------------------

        @staticmethod
        def _split_wallet_path(path: str):
            """/v1/wallets/<wallet_id>/<rest...> -> (wallet_id, rest)，否则 None。"""
            if not path.startswith(_WALLETS_PREFIX):
                return None
            parts = path[len(_WALLETS_PREFIX):].split("/")
            if not parts[0]:
                return None
            return parts[0], parts[1:]

        @staticmethod
        def _is_sign_session_cancel_path(rest) -> bool:
            """rest 是否为 sign-sessions/<sid>/cancel（仅接受 POST）。"""
            return (
                len(rest) == 3
                and rest[0] == "sign-sessions"
                and rest[2] == "cancel"
            )

        @staticmethod
        def _is_share_rotation_cancel_path(rest) -> bool:
            """rest 是否为 share-rotations/<rid>/cancel（仅接受 POST）。"""
            return (
                len(rest) == 3
                and rest[0] == "share-rotations"
                and rest[2] == "cancel"
            )

        @classmethod
        def _is_cancel_path(cls, rest) -> bool:
            """rest 是否为仅接受 POST 的撤销路径（会话/轮换）。"""
            return cls._is_sign_session_cancel_path(
                rest
            ) or cls._is_share_rotation_cancel_path(rest)

        @staticmethod
        def _split_dkg_path(path: str):
            """/v1/dkg/<wallet_id>/<dkg_id> -> (wallet_id, dkg_id)，否则 None。"""
            if not path.startswith(_DKG_PREFIX):
                return None
            parts = path[len(_DKG_PREFIX):].split("/")
            if len(parts) != 2 or not parts[0] or not parts[1]:
                return None
            return parts[0], parts[1]

        @staticmethod
        def _split_dkg_failover_path(path: str):
            """/v1/dkg/<wallet_id>/<dkg_id>/failover -> (wallet_id, dkg_id)，否则 None。"""
            if not path.startswith(_DKG_PREFIX):
                return None
            parts = path[len(_DKG_PREFIX):].split("/")
            if (
                len(parts) != 3
                or not parts[0]
                or not parts[1]
                or parts[2] != "failover"
            ):
                return None
            return parts[0], parts[1]

    return _Handler


